const payload = $json.body ?? $json;
const event = String(payload.event ?? '').toLowerCase().replace(/[_-]/g, '.');
const rawData = payload.data ?? {};
const data = Array.isArray(rawData) ? (rawData[0] ?? {}) : rawData;
const instance = String(payload.instance ?? payload.instanceName ?? '');
if (!instance) return [];

if (event === 'call') {
  const status = String(data.status ?? data.state ?? '').toLowerCase();
  if (status && !['offer', 'ringing', 'incoming'].includes(status)) return [];
  const callerJid = String(data.from ?? data.remoteJid ?? data.chatId ?? data.key?.remoteJid ?? '');
  if (!callerJid || callerJid.endsWith('@g.us') || callerJid.includes('@newsletter')) return [];
  const number = callerJid.split('@')[0].split(':')[0].replace(/\D/g, '');
  const callId = String(data.id ?? data.callId ?? data.call_id ?? '');
  if (!number || !callId) return [];
  const remoteJid = callerJid.includes('@') ? callerJid : `${number}@s.whatsapp.net`;
  return [{ json: {
    channel: 'whatsapp',
    eventType: 'call',
    instance,
    number,
    remoteJid,
    conversationId: `whatsapp:${instance}:${remoteJid}`,
    messageId: `call:${callId}`,
    firstName: String(data.pushName ?? data.notifyName ?? '').slice(0, 80),
    language: 'pt-BR',
    text: ''
  } }];
}

if (event !== 'messages.upsert') return [];
const key = data.key ?? data.message?.key ?? {};
const remoteJid = String(key.remoteJid ?? data.remoteJid ?? '');
const deliveryJid = remoteJid.endsWith('@lid')
  ? String(key.remoteJidAlt ?? data.remoteJidAlt ?? remoteJid)
  : remoteJid;

if (!remoteJid || key.fromMe === true) return [];
if (remoteJid.endsWith('@g.us') || remoteJid === 'status@broadcast' || remoteJid.includes('@newsletter')) return [];

const message = data.message ?? {};
const unwrapped = message.ephemeralMessage?.message ?? message.viewOnceMessage?.message ?? message;
const text = String(
  unwrapped.conversation ??
  unwrapped.extendedTextMessage?.text ??
  unwrapped.imageMessage?.caption ??
  unwrapped.videoMessage?.caption ??
  ''
).trim();
if (!text || !key.id) return [];

const number = deliveryJid.split('@')[0].split(':')[0].replace(/\D/g, '');
if (!number) return [];

return [{
  json: {
    channel: 'whatsapp',
    eventType: 'message',
    instance,
    number,
    remoteJid,
    conversationId: `whatsapp:${instance}:${remoteJid}`,
    messageId: String(key.id),
    firstName: String(data.pushName ?? data.notifyName ?? '').slice(0, 80),
    language: 'pt-BR',
    text
  }
}];

const inbound = $('Normalizar e Filtrar Evento').first().json;
const result = $json;
if (result.duplicate === true || !Array.isArray(result.messages)) return [];

const language = String(result.language || inbound.language || 'pt-BR').toLowerCase();
const languageKey = language.startsWith('en')
  ? 'en'
  : language.startsWith('de')
    ? 'de'
    : language.startsWith('fr')
      ? 'fr'
      : language.startsWith('es')
        ? 'es'
        : 'pt';
const ctaCopy = {
  pt: {
    body: 'Toque no botão abaixo para continuar com nossa equipe comercial. Sua mensagem já estará preenchida.',
    label: 'Falar com a equipe'
  },
  en: {
    body: 'Tap the button below to continue with our sales team. Your message will already be filled in.',
    label: 'Talk to our team'
  },
  de: {
    body: 'Tippen Sie auf die Schaltfläche unten, um mit unserem Vertriebsteam fortzufahren. Ihre Nachricht ist bereits ausgefüllt.',
    label: 'Zum Vertrieb'
  },
  fr: {
    body: 'Touchez le bouton ci-dessous pour continuer avec notre équipe commerciale. Votre message sera déjà préremplie.',
    label: 'Contacter l’équipe'
  },
  es: {
    body: 'Toca el botón de abajo para continuar con nuestro equipo comercial. Tu mensaje ya estará preparado.',
    label: 'Hablar con el equipo'
  }
};
const commercialPrefix = 'https://wa.me/5511967702212?text=';

function commercialUrlFrom(text) {
  const start = text.indexOf(commercialPrefix);
  if (start < 0) return '';
  const tail = text.slice(start, start + 4096);
  let end = tail.length;
  for (const whitespace of [' ', '\n', '\r', '\t']) {
    const position = tail.indexOf(whitespace);
    if (position >= 0) end = Math.min(end, position);
  }
  try {
    const parsed = new URL(tail.slice(0, end));
    if (parsed.protocol !== 'https:'
      || parsed.hostname !== 'wa.me'
      || parsed.pathname !== '/5511967702212'
      || !parsed.searchParams.get('text')) return '';
    return parsed.toString();
  } catch {
    return '';
  }
}

return result.messages
  .map((text) => String(text ?? '').trim())
  .filter(Boolean)
  .map((text, index) => {
    const ctaUrl = commercialUrlFrom(text);
    if (ctaUrl) {
      return { json: {
        instance: inbound.instance,
        number: inbound.number,
        messageType: 'commercial_cta',
        text: ctaCopy[languageKey].body,
        ctaLabel: ctaCopy[languageKey].label,
        ctaUrl,
        delay: 5000,
        order: index
      } };
    }
    return { json: {
      instance: inbound.instance,
      number: inbound.number,
      messageType: 'text',
      text: text.slice(0, 4000),
      delay: 5000,
      order: index
    } };
  });
